    if route == 14 {
        // predicated block (arm 14): `C [s] rA op rhs then_units else_units`
        let b = decode_if_block(insn.raw)?;
        let rhs = match b.rhs { Rhs::Reg(r) => format!("r{}", r), Rhs::Imm(v) => format!("{}", v), Rhs::Bit(r) => format!("1<<r{}", r) };
