/// R-HARN-3: LED duty per sample.
#[test]
fn led_capture() {
    let mut o = opts(20);
    o.leds_every_us = Some(5_000);
    let r = run(&image("leds"), &o).unwrap();
    let csv = String::from_utf8(output(&r, "leds.csv").to_vec()).unwrap();
    let rows: Vec<Vec<&str>> = csv.lines().map(|l| l.split(',').collect()).collect();
    assert_eq!(rows[0].len(), 42);
    assert_eq!((rows[0][6], rows[0][35]), ("led5", "led34"));
    let at = |t: &str, col: usize| rows.iter().find(|r| r[0] == t).unwrap()[col];
    assert_eq!((at("5", 6), at("5", 35)), ("1000", "0"));
    assert_eq!((at("15", 6), at("15", 35)), ("0", "1000"));
}

/// R-HARN-3: flash in and out, and the image in the chip.
#[test]
51:| R-HARN-1 | `fwtest` boots a raw image as docs/HARNESS.md says (load address, size limit, entry, initial state, memory), and refuses images it can't load. | M0b | C-HARNESS-TEST, C-HARNESS-SUITE-A |
52:| R-HARN-2 | A timed input script drives keys, encoders, the pot and MIDI in, in the text format docs/HARNESS.md gives. | M0b | C-HARNESS-TEST, C-HARNESS-SUITE-A |
53:| R-HARN-3 | Captures, as asked: RAM regions, the LCD as PNG, LED duty, the flash chip, audio as WAV, instructions per audio block, the debug console. | M0b | C-HARNESS-TEST, C-HARNESS-SUITE-A |
54:| R-HARN-4 | A fault, a halt and a hang (watchdog) are detected and told apart by exit code; bad input has its own code. | M0b | C-HARNESS-TEST, C-HARNESS-SUITE-A |
55:| R-HARN-5 | Golden files compare exactly, unless a tolerance file allows a documented difference (PNG pixels, WAV samples, CSV numbers). | M0b | C-HARNESS-TEST, C-HARNESS-SUITE-A |
56:| R-HARN-6 | Determinism: the same image, script and fwtest build give byte-identical outputs on every run and machine (no JIT, no host time, no environment influence). | M0b | C-HARNESS-TEST, C-HARNESS-SUITE-B, C-HARNESS-DET |
57:| R-HARN-7 | Every run writes `result.json` and `junit.xml`; the harness suite's are kept in the commit's record (`harness/`). | M0b | C-HARNESS-TEST, C-HARNESS-SUITE-A |
58:| R-HARN-8 | fwtest builds in a container whose bases are pinned by digest, offline, with the Rust toolchain pinned and no third-party crates (Cargo.lock lists path crates only); the harness's test images rebuild identically with the pinned toolchain. | M0b | C-HARNESS-IMAGE, C-HARNESS-IMAGES |
59:| R-HARN-9 | The harness runs raw images only: it never uses the vendored crates' update-package or stock-boot paths, nor anything of M-VAVE's. | M0b | C-HARNESS-SCOPE |
60:| R-HARN-10 | The firmware side's wrapper `tools/fwtest` runs the published image with no network, as linux/amd64, with the working folder read-only and only `--out` writable. | M0b | C-FWTEST-PIN |

