    assert_eq!(&w[0..4], &[s(4), s(5), s(6), SRC + 0x10], "A {{r3, r1, r0}} = [r6+]");
    assert_eq!(&w[4..7], &[s(8), s(9), SRC + 0x28], "B {{r2, r1}} = [r7++]");
    assert_eq!(&w[7..10], &[s(2), s(3), SRC + 0x10], "C {{r3, r0}} = [-r4]");
