    want[9..12].copy_from_slice(&[0xc0, 0xce, 0xcf]); // G [--r13] = {r15, r14, r0}
    want[16..18].copy_from_slice(&[0xd3, 0xd6]); // H [r10+] = {r6, r3}
    want[20..23].copy_from_slice(&[0xe1, 0xe2, 0xe4]); // I [r11++] = {r4, r2, r1}
