# Reads corpus/*.dis; writes units.tsv: one line per distinct instruction unit (a dual-issue
# pair is one unit): hex bytes, a normalised form, the text, and where it was first seen.
import glob, re, sys
line = re.compile(r'^\s*([0-9a-f]+):\s+((?:[0-9a-f]{2} )+)\s*\t(.*)$')
units = {}
for f in sorted(glob.glob('corpus/*.dis')):
    pend = None
    for l in open(f):
        m = line.match(l.rstrip('\n'))
        if not m:
            continue
        b = m.group(2).replace(' ', '')
        t = m.group(3).strip()
        if pend:
            b, t = pend[0] + b, pend[1] + ' ' + t
            pend = None
        elif t.endswith('#'):
            pend = (b, t)
            continue
        if b not in units:
            units[b] = (t, f.split('/')[-1])
def norm(t):
    t = re.sub(r'<[^>]*>', '', t)
    t = re.sub(r'\br\d+\b', 'R', t)
    t = re.sub(r'-?\b(0x[0-9A-Fa-f]+|\d+)\b', 'N', t)
    return re.sub(r'\s+', ' ', t).strip()
with open('units.tsv', 'w') as o:
    for b, (t, f) in units.items():
        o.write('%s\t%s\t%s\t%s\n' % (b, norm(t), t, f))
forms = {norm(t) for t, _ in units.values()}
print(len(units), 'distinct units,', len(forms), 'forms')
EOF
